    /// <summary>
    /// method of payment lookup - added by TCS
    /// </summary>
    /// <param name="sender"></param>
    /// <param name="e"></param>
    [FormControlEventHandler(formControlStr(LedgerJournalTransVendPaym, LedgerJournalTrans_PaymMode1), FormControlEventType::Lookup)]
    public void LedgerJournalTrans_PaymMode1_OnLookup(FormControl sender, FormControlEventArgs e)
    {
        FormControlCancelableSuperEventArgs event = e as FormControlCancelableSuperEventArgs;
        event.CancelSuperCall();

        SysTableLookup          sysTableLookup = SysTableLookup::newParameters(tableNum(VendPaymModeTable), sender);
        Query                   query = new Query();
        QueryBuildDataSource    queryBuildDataSource;
        QueryBuildRange         queryBuildRange;
        container               conPaymMode;
        str                     strPaymMode;
        FormRun                 formRun;
        FormDataSource          formDS;
        LedgerJournalTrans      lgTrans;
        LedgerJournalTable      lgt;
        LedgerJournalName       lgN;
        str                     strJournalNum;
        str                     strMOP;
        container               conMOP;

        strJournalNum = sender.formRun().design().controlname(formcontrolstr(LedgerJournalTransVendPaym,LedgerJournalTrans_JournalNum)).valueStr();
     
        select firstonly lgt where lgt.JournalNum == strJournalNum;

        select firstonly lgN where lgN.JournalName == lgt.JournalName;

        strMOP = lgN.MET_PaymMode;
        conMOP = str2con(strMOP,"@MET:Semicoln");

               
        queryBuildDataSource = query.addDataSource(tableNum(VendPaymModeTable));

        
        for (int i; i <= conLen(conMOP); i++)
        {
            strMOP = conPeek(conMOP,i);
            queryBuildRange = queryBuildDataSource.addRange(fieldNum(VendPaymModeTable,PaymMode));
            queryBuildRange.value(strMOP);
        }
        
        sysTableLookup.addLookupfield(fieldNum(VendPaymModeTable, Paymmode));
 
        sysTableLookup.parmQuery(query);
        sysTableLookup.performFormLookup();
    }
